  [428717] = { "Explosive Shotとすべてのダメージ罠の与えるダメージが$N1%増加します。さらに、Explosive Trapの初撃ダメージとImmolation Trapの継続ダメージの合計が、近接または遠隔のAttack Powerの$N2%分増加します。", nil, 0x41837b4a, nil, "um" },
