  [428739] = { "$D1の間、対象をスタンさせます。Frozen状態の対象にのみ使用できます。Stunを永続的に無効化する対象には$N2のダメージを与えます。このダメージはGlaciateのスタックの恩恵を受けますが、スタックを消費しません。", "スタンし、Frozen状態です。", 0x477daf2a, 0xf27e935d, "uu" },
